import { useEffect, type ReactNode } from 'react'
import { I18nextProvider } from 'react-i18next'
import i18n from '@/shared/i18n/i18n'
import { useTenant } from './TenantProvider'

export function LocaleProvider({ children }: { children: ReactNode }) {
  const { manifest } = useTenant()

  useEffect(() => {
    if (!manifest) return
    const savedLocale = localStorage.getItem('nox-locale')
    const locale = savedLocale ?? manifest.localization.defaultLocale
    if (manifest.localization.enabledLocales.includes(locale)) {
      i18n.changeLanguage(locale)
    } else {
      i18n.changeLanguage(manifest.localization.defaultLocale)
    }
  }, [manifest])

  return <I18nextProvider i18n={i18n}>{children}</I18nextProvider>
}
